#include <stdio.h>

#define MAX(a,b) ((a) > (b) ? (a) : (b))

#define MAX_SIZE 10000

int main() {
    int incomes[MAX_SIZE];
    int incomes_size = 0;

    int num;
    char unit;

    while(scanf("%d%c", &num, &unit)) {
        incomes[incomes_size] = num * (unit == 'Y' ? 1 : 7);
        incomes_size++;
        if(getchar() != ' ') break;
    }

    int ans = 0;
    for(int i=1; i<incomes_size; i++) {
        ans += MAX(0, incomes[i] - incomes[i-1]);
    }

    printf("%d\n", ans);

    return 0;
}
